from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

def decrypt_aes_cbc(iv: bytes, key: bytes, ciphertext: bytes) -> bytes:
    """
    Décrypte un message chiffré en mode AES-CBC-256.

    :param iv: Vecteur d'initialisation de 16 octets.
    :param key: Clé de déchiffrement de 32 octets.
    :param ciphertext: Message chiffré (taille multiple de 16).
    :return: Message déchiffré (bytes).
    """
    if len(iv) != 16:
        raise ValueError("L'IV doit avoir une longueur de 16 octets.")
    if len(key) != 32:
        raise ValueError("La clé doit avoir une longueur de 32 octets.")
    if len(ciphertext) % 16 != 0:
        raise ValueError("La longueur du message chiffré doit être un multiple de 16 octets.")

    cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
    decryptor = cipher.decryptor()
    plaintext = decryptor.update(ciphertext) + decryptor.finalize()

    return plaintext

def bitstring_to_bytes(s: str) -> bytes:
    """
    Convertit une chaîne de bits en octets.

    :param s: Chaîne de bits.
    :return: Octets.
    """
    return int(s, 2).to_bytes((len(s) + 7) // 8, byteorder='big')

iv = b"KU4VQMKESDCDM\x00\x00\x00"


def bin_to_text(binaire):
    """Traduit plusieurs octets codés en binaire en texte en ASCII
    mais ne garde que les lettres de l'alphabet (majuscules et minuscules) et les chiffres.
    
    Args:
        binaire (str): une chaîne d'octets codés en binaire

    Returns:
        str: un message composé uniquement de lettres et de chiffres
    """    
    i = 0
    texte = ""
    avant = ""
    while i < len(binaire):
        octet = ""
        for num in range(i, i + 8):
            octet += binaire[num]
        i = i + 8
        char = chr(int(octet, 2))  # Convertir l'octet binaire en caractère
        
        # Ajouter le caractère uniquement s'il fait partie de l'alphabet ou des chiffres
        if char.isalpha() or char.isdigit():
            texte += char
        
        # Arrêter si deux espaces consécutifs sont détectés
        if avant == " " and char == " ":
            return texte
        avant = char
    
    return texte

