def nettoyer_texte(texte: bytes) -> str:
    """
    Nettoie le texte déchiffré en supprimant les caractères non alphabétiques ou non numériques.
    
    :param texte: Le texte déchiffré sous forme de bytes.
    :return: Le texte nettoyé sous forme de chaîne.
    """
    texte_str = texte.decode('utf-8', errors='ignore')  # Décodage en UTF-8
    texte_nettoye = ''.join([char for char in texte_str if char.isalnum() or char.isspace()])
    return texte_nettoye

